class Solution {
public:
    int findLHS(vector<int>& nums) {
        map<int, int> cnt;
        for (int x : nums) cnt[x]++;
        int best = 0;
        for (auto& [v, c] : cnt) {
            if (cnt.count(v + 1)) best = max(best, c + cnt[v + 1]);
        }
        return best;
    }
};
